'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readSaved=key=>{try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v.filter(id=>TOOLS.some(t=>t.id===id)):[]}catch{return[]}};
const state={view:'explore',category:'all',query:'',level:'all',delivery:'all',core:false,bookOnly:false,compared:readSaved('atlas-compare').slice(0,4),saved:readSaved('atlas-saved')};
const cfg={preset:'shop',platform:'쇼핑몰',env:'local',source:'db',latency:'daily',volume:'small',team:'small',consumers:'one',replay:true,quality:true};
const PRESETS={shop:{platform:'쇼핑몰 주문·고객 매출 분석',source:'db',latency:'daily',volume:'small',consumers:'one'},logs:{platform:'서비스 운영 로그 분석',source:'events',latency:'realtime',volume:'medium',consumers:'many'},iot:{platform:'IoT 센서 모니터링',source:'events',latency:'realtime',volume:'large',consumers:'many'},saas:{platform:'SaaS 고객 사용량·업무 데이터 분석',source:'api',latency:'hourly',volume:'medium',consumers:'one'},ai:{platform:'AI 문서 데이터 전처리',source:'files',latency:'daily',volume:'medium',consumers:'one'},finance:{platform:'금융 거래 변경·이상 징후 분석',source:'db',latency:'realtime',volume:'medium',consumers:'many'}};
let simulationTimer=null, simulationStats={processed:0,retries:0,stage:0},lastPlan=null;
function persist(){try{localStorage.setItem('atlas-compare',JSON.stringify(state.compared));localStorage.setItem('atlas-saved',JSON.stringify(state.saved))}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function catName(id){return CATEGORIES.find(c=>c[0]===id)?.[1]||id}
function toolBy(name){return TOOLS.find(t=>t.name===name)}
function icon(t){const i=CATEGORIES.findIndex(c=>c[0]===t.category),p=PALETTES[i%PALETTES.length];const label=({'Apache Kafka':'Kf','Apache Spark':'Sp','Apache Flink':'Fl','PostgreSQL':'Pg','Python':'Py','SQL':'SQL','dbt':'dbt','Docker':'Dk','Airbyte':'Ab','Parquet':'Pq','DuckDB':'Dk','BigQuery':'Bq'})[t.name]||t.name.replace(/^(Apache |Amazon |Cloud |AWS )/,'').slice(0,2);return `<span class="tool-icon" style="--tool-color:${p[0]};--tool-bg:${p[1]}">${esc(label)}</span>`}
function head(kicker,title,description,extra=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${description}</p></div>${extra}</div>`}
function navUpdate(){ $$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#crumb').textContent=({explore:'도구 탐색',lab:'파이프라인 랩',compare:'비교함'})[state.view];$('#navCount').textContent=TOOLS.length;$('#compareCount').textContent=state.compared.length;$('#categories').innerHTML=`<button data-category="all" class="${state.category==='all'&&state.view==='explore'?'selected':''}">전체 도구 <small>${TOOLS.length}</small></button>`+CATEGORIES.map(c=>`<button data-category="${c[0]}" class="${state.category===c[0]&&state.view==='explore'?'selected':''}">${c[1]} <small>${TOOLS.filter(t=>t.category===c[0]).length}</small></button>`).join('');tray()}
function tray(){const el=$('#tray');el.hidden=!state.compared.length||state.view==='compare';el.innerHTML=`<b>${state.compared.length}개 도구 선택</b><span class="names">${state.compared.map(id=>esc(TOOLS.find(t=>t.id===id).name)).join(' · ')}</span><button class="clear" data-clear-compare>초기화</button><button class="btn primary" data-view="compare">나란히 비교 ⇄</button>`}
function stopSimulation(){if(simulationTimer){clearInterval(simulationTimer);simulationTimer=null}}
function navigate(view){stopSimulation();state.view=view;$('#detail').close();$('.sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})}
function render(){navUpdate();if(state.view==='explore')renderExplore();else if(state.view==='lab')renderLab();else renderCompare()}
function renderExplore(){const cat=state.category==='all'?'전체 도구':catName(state.category);$('#main').innerHTML=head('YOUR DATA STACK, EXPLAINED.','데이터 도구, 선택의 근거까지.','특징과 장단점을 살펴보고, 우리 상황에 맞는 도구를 찾아보세요.',`<button class="btn primary" data-view="lab">파이프라인 설계해 보기 <span>↗</span></button>`)+`<section class="stats" aria-label="도구 지도 요약"><div class="stat"><label>탐색할 기술·도구</label><span class="stat-symbol">▦</span><strong>${TOOLS.length}<small>개 도구</small></strong></div><div class="stat"><label>파이프라인 역할</label><span class="stat-symbol">⌘</span><strong>${CATEGORIES.length}<small>개 분류</small></strong></div><div class="stat"><label>설계 시나리오</label><span class="stat-symbol">↗</span><strong>6<small>개 시작점</small></strong></div><div class="stat"><label>북마크한 도구</label><span class="stat-symbol">☆</span><strong>${state.saved.length}<small>개 저장됨</small></strong></div></section><section class="feature"><div class="feature-icon">⇢</div><div><h3>“이 서비스라면 어떤 파이프라인이 필요할까?”</h3><p>서비스 유형과 데이터 조건을 바꿔보세요. 구조와 선택 이유가 함께 달라집니다.</p></div><button class="btn soft" data-view="lab">파이프라인 랩 열기 →</button></section><section aria-label="도구 목록"><div class="section-head"><h2>${esc(cat)} <span>역할부터 이해하는 기술 지도</span></h2><button class="filter-switch ${state.bookOnly?'on':''}" id="bookmarkFilter">${state.bookOnly?'★ 북마크만 보는 중':'☆ 북마크만 보기'}</button></div><div class="search-bar"><div class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="도구·기능·사용 상황 검색" placeholder="도구 이름, 해결할 문제, 사용 상황으로 검색…" value="${esc(state.query)}"></div><select id="levelFilter" aria-label="학습 난이도"><option value="all">모든 학습 난이도</option>${['입문','중급','심화'].map(v=>`<option ${state.level===v?'selected':''}>${v}</option>`).join('')}</select><select id="deliveryFilter" aria-label="도구 제공 방식"><option value="all">모든 제공 방식</option>${[...new Set(TOOLS.map(t=>t.delivery))].map(v=>`<option ${state.delivery===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="chips">${[['all','전체 보기'],['core','핵심 도구 먼저'],['processing','계산·처리'],['messaging','메시지·이벤트'],['database','DB·분석·조회'],['orchestration','실행·예약'],['format','저장 형식']].map(([id,label])=>`<button class="chip ${(id==='core'?state.core:id===state.category&&!state.core)?'active':''}" data-chip="${id}">${label}</button>`).join('')}</div><div class="count-line"><p class="result-meta" id="resultCount"></p><button class="text-btn" id="resetFilters">필터 초기화</button></div><div class="tools-grid" id="toolGrid"></div><p class="source-note">장단점·난이도는 학습을 위한 정성적 요약입니다. 상세 보기에서 각 도구의 공식 문서를 확인할 수 있습니다.</p></section>`;renderCards();$('#search').addEventListener('input',e=>{state.query=e.target.value;renderCards()});$('#levelFilter').addEventListener('change',e=>{state.level=e.target.value;renderCards()});$('#deliveryFilter').addEventListener('change',e=>{state.delivery=e.target.value;renderCards()})}
function filteredTools(){const q=state.query.trim().toLocaleLowerCase();return TOOLS.filter(t=>(state.category==='all'||t.category===state.category)&&(!state.core||CORE.includes(t.name))&&(!state.bookOnly||state.saved.includes(t.id))&&(state.level==='all'||t.level===state.level)&&(state.delivery==='all'||t.delivery===state.delivery)&&(!q||[t.name,t.desc,t.pro,t.con,t.fit,catName(t.category)].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>q?Number(b.name.toLocaleLowerCase().includes(q))-Number(a.name.toLocaleLowerCase().includes(q)):Number(CORE.includes(b.name))-Number(CORE.includes(a.name)))}
function renderCards(){const tools=filteredTools();$('#resultCount').textContent=`${tools.length}개 결과 · 카드를 열어 적합한 상황과 대안을 살펴보세요`;$('#toolGrid').innerHTML=tools.length?tools.map(t=>`<article class="tool-card"><div class="card-top">${icon(t)}<div><div class="tool-name">${esc(t.name)}</div><div class="tool-category">${catName(t.category)}</div></div><button class="save ${state.saved.includes(t.id)?'on':''}" data-save="${t.id}" aria-label="${esc(t.name)} 북마크" aria-pressed="${state.saved.includes(t.id)}">${state.saved.includes(t.id)?'★':'☆'}</button></div><p class="tool-desc">${esc(t.desc)}</p><div class="tags"><span class="tag">${esc(t.delivery)}</span><span class="tag">학습 ${t.level}</span>${CORE.includes(t.name)?'<span class="tag">핵심 개념</span>':''}</div><div class="trade pro"><b>장점</b><span>${esc(t.pro)}</span></div><div class="trade con"><b>고려</b><span>${esc(t.con)}</span></div><div class="card-actions"><button class="text-btn" data-detail="${t.id}">언제 쓰면 좋을까? ↗</button><button class="compare-btn ${state.compared.includes(t.id)?'on':''}" data-compare="${t.id}" aria-pressed="${state.compared.includes(t.id)}">${state.compared.includes(t.id)?'✓ 선택됨':'+ 비교'}</button></div></article>`).join(''):`<div class="empty"><h3>조건에 맞는 도구가 없어요.</h3><p>검색어를 줄이거나 필터를 초기화해 보세요.</p><button class="btn" id="emptyReset">필터 초기화</button></div>`}
function toggleCompare(id){if(state.compared.includes(id))state.compared=state.compared.filter(x=>x!==id);else{if(state.compared.length>=4)return toast('한 번에 최대 4개까지 비교할 수 있어요.');state.compared.push(id)}persist();navUpdate();if(state.view==='explore')renderCards();else if(state.view==='compare')renderCompare();if($('#detail').open&&$('#detailBody [data-detail-current]'))detail(id)}
function detail(id){const t=TOOLS.find(t=>t.id===id);if(!t)return;const peers=TOOLS.filter(x=>x.category===t.category&&x.id!==t.id).slice(0,5);$('#detailBody').innerHTML=`<div class="modal-header" data-detail-current="${t.id}">${icon(t)}<div><div class="panel-label">${catName(t.category)}</div><h2>${esc(t.name)}</h2></div><button class="close" data-close aria-label="상세 닫기">×</button></div><div class="modal-content"><p>${esc(t.desc)}</p><div class="tags"><span class="tag">${t.delivery}</span><span class="tag">학습 난이도 ${t.level}</span></div><div class="detail-grid"><section class="detail-block"><h3 style="color:var(--green)">+ 장점·특징</h3><p>${esc(t.pro)}</p></section><section class="detail-block"><h3 style="color:#ae7c45">− 단점·검토할 점</h3><p>${esc(t.con)}</p></section><section class="detail-block wide"><h3>이럴 때 후보로 검토하세요</h3><p>${esc(t.fit)}</p></section><section class="detail-block wide"><h3>같은 역할에서 함께 살펴볼 도구</h3><p>서로 대안이거나 함께 쓸 수 있습니다. 기능·운영 모델은 개별 확인하세요.</p><div class="chips" style="margin:10px 0 0">${peers.map(x=>`<button class="chip" data-detail="${x.id}">${esc(x.name)} ↗</button>`).join('')||'이 분류의 다른 도구가 없습니다.'}</div></section></div><div class="lab-actions"><button class="btn primary" data-compare="${t.id}">${state.compared.includes(t.id)?'비교함에서 제거':'비교함에 추가'}</button><a class="btn" href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">공식 문서 ↗</a></div><p class="scenario-note">비용·지원 기능·라이선스는 배포 방식과 버전에 따라 다릅니다. 실제 도입 전 공식 문서에서 확인하세요.</p></div>`;if(!$('#detail').open)$('#detail').showModal()}
function renderCompare(){const selected=state.compared.map(id=>TOOLS.find(t=>t.id===id));$('#main').innerHTML=head('MAKE THE TRADE-OFF VISIBLE.','도구를 나란히 비교하세요.','같은 역할의 대안을 비교하거나, 서로 다른 도구의 책임을 구분해 보세요.',`<button class="btn" data-view="explore">도구 더 고르기 +</button>`)+(selected.length?`<div class="notice" style="margin-bottom:20px">같은 분류여도 완전한 대체재는 아닙니다. 예: Spark는 계산 엔진, PySpark는 Python API입니다. 관리형 서비스와 자체 운영 도구의 비교는 운영 책임까지 살펴보세요.</div><div class="compare-scroll"><table class="comparison"><thead><tr><th>비교 항목</th>${selected.map(t=>`<th>${icon(t)}<p style="margin:10px 0">${esc(t.name)}</p><button class="text-btn" data-compare="${t.id}">선택 해제 ×</button></th>`).join('')}</tr></thead><tbody>${[['역할',t=>catName(t.category)],['무엇을 하나',t=>t.desc],['장점',t=>t.pro],['단점·고려',t=>t.con],['추천 상황',t=>t.fit],['제공 방식',t=>t.delivery],['학습 난이도',t=>t.level],['공식 정보',t=>`<a href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">공식 문서 ↗</a>`]].map(([title,fn])=>`<tr><td>${title}</td>${selected.map(t=>`<td>${title==='공식 정보'?fn(t):esc(fn(t))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div style="margin-top:18px"><button class="btn" data-clear-compare>비교함 비우기</button></div>`:`<div class="empty"><h3>비교할 도구를 골라주세요.</h3><p>도구 카드의 ‘+ 비교’를 누르면 최대 4개를 나란히 볼 수 있어요.</p><button class="btn primary" data-view="explore">도구 탐색하기 →</button></div>`)}
function selectField(name,label,options){return `<div class="field"><label for="cfg-${name}">${label}</label><select id="cfg-${name}" name="${name}">${options.map(([v,l])=>`<option value="${v}" ${cfg[name]===v?'selected':''}>${l}</option>`).join('')}</select></div>`}
function renderLab(){const p=PRESETS;$('#main').innerHTML=head('FROM REQUIREMENTS TO ARCHITECTURE.','우리 서비스의 파이프라인 랩.','서비스와 조건을 바꾸며 구조를 탐색하세요. 도구 선택의 근거와 대안을 함께 보여줍니다.',`<span class="mode-label">● 브라우저에서 실행되는 설계 실험</span>`)+`<div class="lab-layout"><aside class="panel config-panel"><div class="panel-label">01 / REQUIREMENTS</div><h2>어떤 서비스를 만드나요?</h2><div class="presets">${Object.entries(p).map(([key,v])=>`<button class="preset" data-preset="${key}">${({shop:'쇼핑몰',logs:'로그',iot:'IoT',saas:'SaaS',ai:'AI 문서',finance:'금융'})[key]}</button>`).join('')}</div><form id="configForm"><div class="field full-row"><label for="platformText">플랫폼·서비스 설명</label><textarea id="platformText" name="platform" placeholder="예: AWS에서 주문 변경을 실시간 분석하는 쇼핑몰">${esc(cfg.platform)}</textarea><small>설명에서 알려진 유형·환경을 찾아 조건에 적용합니다.</small><button class="text-btn" id="interpret" type="button">설명에서 조건 가져오기 ↗</button><small id="interpretFeedback" aria-live="polite"></small></div>${selectField('env','운영 환경',[['local','로컬·자체 환경'],['aws','AWS'],['gcp','Google Cloud'],['azure','Azure']])}${selectField('source','주요 데이터 원본',[['db','서비스 DB'],['api','외부 API / SaaS'],['files','파일 / 문서'],['events','앱 이벤트 / 로그 / 센서']])}${selectField('latency','결과 반영 목표',[['daily','하루 한 번'],['hourly','약 1시간 간격'],['realtime','수초~수분 내 반영 목표']])}${selectField('volume','처리 규모 가정',[['small','소규모 · 한 장비 우선 검토'],['medium','중규모 · 엔진 성능 검증 필요'],['large','대규모 · 분산/관리형 검토']])}${selectField('team','운영 여력',[['small','적은 인력 · 운영 단순화 우선'],['expert','플랫폼 운영 인력 있음']])}${selectField('consumers','같은 데이터의 사용처',[['one','주요 분석 목적지 1개'],['many','여러 독립적인 소비자']])}<div class="full-row"><label class="check-line"><input type="checkbox" name="replay" ${cfg.replay?'checked':''}> 원본 보관·재처리 필요</label><label class="check-line"><input type="checkbox" name="quality" ${cfg.quality?'checked':''}> 품질 검사 포함</label><button class="btn primary full" type="submit">조건으로 구조 다시 만들기 →</button></div></form></aside><section class="lab-results" id="labResults" aria-live="polite"></section></div>`;drawPlan();$('#configForm').addEventListener('submit',e=>{e.preventDefault();syncConfig();stopSimulation();drawPlan();toast('현재 조건으로 파이프라인을 구성했어요.')});$('#configForm').addEventListener('change',()=>{syncConfig();stopSimulation();drawPlan()});$('#interpret').addEventListener('click',interpret)}
function syncConfig(){const f=$('#configForm');for(const key of ['platform','env','source','latency','volume','team','consumers'])cfg[key]=f.elements[key].value;for(const key of ['replay','quality'])cfg[key]=f.elements[key].checked}
function interpret(){syncConfig();const text=cfg.platform.toLowerCase(),found=[];const set=(k,v,label)=>{cfg[k]=v;found.push(label)};if(/aws|아마존/.test(text))set('env','aws','AWS');else if(/gcp|구글|google|bigquery/.test(text))set('env','gcp','Google Cloud');else if(/azure|애저|fabric|패브릭/.test(text))set('env','azure','Azure');else if(/로컬|자체/.test(text))set('env','local','자체 환경');if(/실시간|스트림|초마다|수초/.test(text))set('latency','realtime','연속 반영 목표');else if(/매일|하루|일별|배치/.test(text))set('latency','daily','일 배치');else if(/시간마다|한시간|1시간/.test(text))set('latency','hourly','시간 배치');if(/iot|센서|로그|클릭|이벤트/.test(text))set('source','events','이벤트 원본');else if(/문서|pdf|파일|이미지/.test(text))set('source','files','파일 원본');else if(/api|saas|외부/.test(text))set('source','api','API 원본');else if(/주문|쇼핑|거래|db|데이터베이스/.test(text))set('source','db','DB 원본');if(/대규모|테라|tb|수억/.test(text))set('volume','large','대규모 가정');else if(/소규모|작은|학습/.test(text))set('volume','small','소규모 가정');if(/여러.*소비|여러.*서비스|다수.*소비/.test(text))set('consumers','many','여러 소비자');stopSimulation();renderLab();$('#interpretFeedback').textContent=found.length?`인식한 조건: ${found.join(' · ')}. 아래 항목을 직접 확인·수정하세요.`:'설명에서 조건을 확정하기 어려워 기존 값을 유지했습니다. 아래 항목을 직접 선택하세요.';toast(found.length?'인식한 조건을 적용했어요. 아래 설정을 확인하세요.':'확인 가능한 조건을 직접 골라주세요.')}
function planPipeline(c){const realtime=c.latency==='realtime',large=c.volume==='large',managed=c.team==='small',cloud=c.env!=='local',multi=c.consumers==='many',stream=realtime&&(c.source==='db'||c.source==='events');const nodes=[],reasons=[],warnings=[],alternatives=[],extras=[];const add=(role,name,note,why,alternative)=>{nodes.push({role,name,note});if(why)reasons.push({name,text:why});if(alternative)alternatives.push(alternative)};
 const sourceName=({db:'서비스 DB',api:'외부 API / SaaS',files:'파일 / 문서',events:'앱 / 센서 이벤트'})[c.source];add('SOURCE',sourceName,'입력 데이터');
 if(c.source==='db'&&stream){const name=c.env==='gcp'&&managed&&!multi?'Datastream':c.env==='aws'&&managed&&!multi?'AWS DMS':'Debezium';add('CAPTURE',name,'변경 데이터 수집','짧은 반영 주기에서는 DB 변경을 지속적으로 전달하는 방식을 검토합니다. 로그 접근 권한·삭제·스냅샷 정책을 확인해야 합니다.','CDC가 불가능하면 변경 시각 기반 증분 조회나 앱 이벤트 발행을 검토하세요.');warnings.push('DB 로그 접근·원본 버전·커넥터·대상 지원 여부를 확인해야 합니다.');}
 else if(c.source==='api'){add('INGEST',cloud&&managed?'Airbyte':'dlt',realtime?'API 증분 폴링':'증분 수집','API 원본은 커넥터나 코드로 증분 수집합니다. 마지막 성공 위치와 페이지네이션 상태를 저장해야 합니다.','커넥터가 맞지 않으면 HTTPX로 수집 로직을 작성하세요.');if(realtime)warnings.push('API 폴링으로 수초 반영이 가능한지는 원본 갱신 주기·호출 제한에 달렸습니다. 웹훅 지원을 먼저 확인하세요.');}
 else if(c.source==='db'){add('EXTRACT','Python','변경분 조회','배치 목표에서는 먼저 변경분 조회를 검토합니다. 삭제·중간 변경 이력이 필요하면 별도 CDC가 필요할 수 있습니다.','API·DB 연동을 표준화하려면 Airbyte, 모든 변경 이력이 필요하면 CDC를 검토하세요.');}
 else if(c.source==='files'){add('INGEST','Python','신규 파일 탐색','파일 목록과 처리 이력을 비교해 새 파일을 가져옵니다. 파일 유형에 맞는 파서를 연결하세요.','파일 도착 이벤트와 작업 큐를 쓰면 주기적 목록 조회를 줄일 수 있습니다.');if(realtime)warnings.push('파일 자체가 완성되고 도착하는 시간보다 결과를 빨리 만들 수는 없습니다. 파일 도착 이벤트 지원을 확인하세요.');}
 else{add('INGEST','수집 SDK / Fluent Bit','이벤트·로그 전달','앱 이벤트는 SDK, 서버 로그는 Fluent Bit 같은 에이전트를 검토합니다. 두 방식은 원본 유형에 따라 다릅니다.');}
 let direct=c.source==='db'&&stream&&c.env==='gcp'&&managed&&!multi;
 if(stream&&!direct){let bus=({aws:managed?'Kinesis Data Streams':'Apache Kafka',gcp:'Cloud Pub/Sub',azure:'Azure Event Hubs',local:'Apache Kafka'})[c.env];if(c.source==='db'&&bus==='Kinesis Data Streams'){bus='Amazon MSK';warnings.push('Debezium→MSK는 Kafka Connect 워커·커넥터 운영이 추가됩니다. 관리형 MSK도 전체 파이프라인 운영을 대신하지 않습니다.');}add('BUFFER',bus,'영속 이벤트 전달',multi?'여러 소비자의 처리 속도와 장애를 분리하기 위해 이벤트 전달 계층을 둡니다. 소비 위치와 재처리 정책이 필요합니다.':'연속 유입을 버퍼링하고 처리 장애 시 따라잡기 위해 영속 전달 계층을 검토합니다.','목적지가 하나이고 직접 복제로 충분하면 브로커를 생략할 수 있습니다.');if(managed&&!cloud)warnings.push('자가 운영 Kafka는 적은 인력에게 부담이 될 수 있습니다. 직접 적재 또는 관리형 플랫폼도 비교하세요.');}
 let store=({aws:'Amazon S3',gcp:'Cloud Storage',azure:'ADLS Gen2',local:'로컬 Parquet'})[c.env];
 if(!stream){add('RAW',store,'원본·중간 파일',c.replay?'원본을 보관하면 수집기를 다시 호출하지 않고 변환 로직을 재실행할 수 있습니다.':'배치 중간 데이터를 파일로 분리합니다. 재처리가 불필요하다면 별도 보관 기간을 짧게 둘 수 있습니다.');if(c.replay)extras.push('원본 보관: '+store);}
 let engine,warehouse,model;
 if(direct){warehouse='BigQuery';add('LOAD',warehouse,'DB 변경 복제 목적지','단일 분석 목적지라면 Datastream의 BigQuery 복제를 우선 후보로 두어 브로커 운영을 줄입니다.');engine='dbt';add('TRANSFORM',engine,'증분 SQL 모델','원본 변경이 도착한 뒤 필요한 집계를 SQL 모델로 만듭니다. 집계 실행 주기는 별도로 보장해야 합니다.');warnings.push('변경 복제 지연과 dbt 집계 주기는 다릅니다. 수초 단위 집계가 필수라면 연속 쿼리·별도 스트림 처리 경로를 비교하세요.');model='CDC 직접 복제';}
 else if(stream){engine=({gcp:'Cloud Dataflow',azure:managed?'관리형 스트림 처리':'Apache Flink',aws:'Apache Flink',local:'Apache Flink'})[c.env];add('PROCESS',engine,'연속 집계·검증','연속 이벤트의 윈도 집계·중복 제거·지연 도착을 처리하는 엔진을 후보로 둡니다. 단순 전달만 필요하면 생략 가능합니다.','필터·단순 가공이면 작은 소비자 프로그램으로 충분할 수 있습니다. Kafka 환경의 JVM 팀은 Kafka Streams도 비교하세요.');warehouse=c.env==='azure'&&managed?'Microsoft Fabric':'ClickHouse';add('SERVE',warehouse,'분석·조회','최종 사용자 조회를 처리 계층과 분리합니다. 이벤트 집계 조회가 빠르게 응답하는지 실제 쿼리로 확인하세요.');if(c.replay)extras.push('원본 보관 분기: 이벤트 → '+store);model='이벤트 스트리밍';}
 else if(large){engine=c.env==='aws'&&managed?'AWS Glue':c.env==='gcp'&&managed?'Cloud Dataproc':c.env==='azure'?'Databricks':'Apache Spark';add('PROCESS',engine,'분산 배치 변환','대규모 조건에서는 분산 처리를 후보로 올립니다. 데이터량만으로 확정하지 않고 조인·셔플·실행 시간을 측정하세요.','SQL 엔진의 집계나 단일 장비 Polars가 기한을 맞춘다면 분산 처리를 줄일 수 있습니다.');warehouse=({aws:'Amazon Redshift',gcp:'BigQuery',azure:'Microsoft Fabric',local:'ClickHouse'})[c.env];add('SERVE',warehouse,'분석 테이블');extras.push('테이블 형식 후보: '+(c.env==='azure'?'Delta Lake':'Apache Iceberg')+' · 엔진 호환성 확인');model='분산 배치';}
 else if(cloud){warehouse=({aws:'Amazon Redshift',gcp:'BigQuery',azure:'Microsoft Fabric'})[c.env];add('LOAD',warehouse,'분석 데이터 적재','관리형 분석 저장소에서 SQL로 처리하면 별도 Spark 클러스터 없이 시작할 수 있습니다.');engine='dbt';add('TRANSFORM',engine,'정제·집계 SQL','분석 테이블이 늘어나면 SQL의 의존성·품질 검사·문서를 모델로 관리합니다.','모델이 소수라면 예약 SQL부터 시작해도 됩니다. dbt 도입 자체가 성능 개선을 보장하지는 않습니다.');model='관리형 ELT';}
 else{engine='DuckDB';warehouse='DuckDB';add('PROCESS',engine,'파일 SQL·집계','소규모·자체 환경에서는 파일을 읽는 SQL 엔진부터 검증합니다. 메모리·디스크·동시 사용자 한계를 확인하세요.','Python 변환이 중심이면 Polars, 지속적인 동시 접속이 필요하면 PostgreSQL 같은 서버 DB를 비교하세요.');if(c.volume==='medium')warnings.push('중규모는 정해진 제품 경계가 아닙니다. 대표 조인·집계를 실행해 한 장비의 처리 기한과 메모리를 확인하세요.');warehouse='PostgreSQL';add('SERVE',warehouse,'집계 결과 적재','대시보드의 지속적인 연결을 위해 결과를 서버형 DB에 적재합니다. DuckDB에서 PostgreSQL로 쓰는 작업은 별도 구현합니다.');model='단일 장비 배치';}
 const bi=c.env==='azure'?'Power BI':c.env==='gcp'?'Looker Studio':c.source==='events'?'Grafana':'Metabase';add('CONSUME',bi,'대시보드 / 분석');
 let orchestration=stream?'지속 실행 서비스 + 재시작·체크포인트 관리':c.env==='gcp'&&managed?'Cloud Composer':c.env==='aws'&&managed?(large?'AWS Step Functions':'Amazon MWAA'):c.env==='azure'?'Azure Data Factory':c.volume==='small'&&c.team==='small'?'cron + 실행 로그':'Apache Airflow';if(direct)orchestration='CDC 지속 실행 + SQL 집계 예약';
 if(c.quality)extras.push(stream?'품질: 처리 단계 검증 + 오류 이벤트 분리':'품질: Great Expectations / dbt tests');extras.push('중복 방지: 원본 키 + 변경 버전 / 이벤트 ID',cloud?'관측: 클라우드 로그·지표 + 실패 알림':'관측: 실행 로그 + 처리 건수·지연 + 실패 알림');if(c.source==='files'&&/ai|문서|pdf/i.test(c.platform)){extras.push('문서 분기: 파싱·필요 시 OCR → 청크 분리 → 버전별 산출물');warnings.push('AI 문서는 민감정보·파서 오류·문서 버전을 관리하세요. 임베딩·벡터 저장소는 검색 요구가 있을 때 추가합니다.');}if(c.source==='db'&&c.latency!=='realtime')warnings.push('변경 시각 기반 추출은 삭제·중간 변경을 놓칠 수 있습니다. 추출 기준과 원본 DB 부하를 검증하세요.');if(large&&c.team==='small')warnings.push('처리 규모가 커도 운영 인력은 적습니다. 자체 클러스터보다 관리형 실행의 총비용을 우선 비교하세요.');if(!stream&&realtime)warnings.push('현재 원본은 파일/API이므로 도착·폴링 기반 증분 경로입니다. 실시간 목표 충족은 별도 검증이 필요합니다.');return{nodes,reasons,warnings,alternatives,extras,orchestration,model,bi,engine,warehouse,stream,config:{...c}};}
function drawPlan(){lastPlan=planPipeline(cfg);const p=lastPlan;$('#labResults').innerHTML=`<section class="architecture"><div class="arch-title"><div><div class="panel-label">02 / PROPOSED ARCHITECTURE</div><h2>${esc(p.model)} 파이프라인</h2></div><span class="tag">조건 기반 초안</span></div><div class="arch-flow" tabindex="0" role="region" aria-label="파이프라인 흐름 · 좌우로 스크롤">${p.nodes.map((n,i)=>`${i?'<span class="arch-arrow">→</span>':''}<div class="arch-node" data-node="${i}"><small>${n.role}</small><strong>${esc(n.name)}</strong><p>${esc(n.note)}</p></div>`).join('')}</div><div class="orchestration">실행 관리 · ${esc(p.orchestration)}</div><p class="scenario-note">화살표는 논리적 데이터 흐름입니다. 실제 연결에는 적재 커넥터·권한·실행 코드가 필요합니다.</p></section><div class="assumptions"><strong>적용한 가정</strong><br>${esc(cfg.platform||'사용자 정의 서비스')} · ${esc(({local:'자체 환경',aws:'AWS',gcp:'Google Cloud',azure:'Azure'})[cfg.env])} · ${esc(({daily:'일 배치',hourly:'시간 배치',realtime:'수초~수분 반영 목표'})[cfg.latency])} · ${esc(({small:'한 장비 우선 검토',medium:'성능 검증 필요',large:'분산 처리 검토'})[cfg.volume])}<br>정해진 수치 기준으로 제품을 확정하지 않습니다. 아래 후보는 벤치마크 전 설계 가설입니다.</div><div class="section-head"><h2>왜 이 도구인가요?</h2><span class="tag">선택 이유 + 대안</span></div><div class="rationale">${p.reasons.map(r=>`<article class="reason"><h3>${esc(r.name)}</h3><p>${esc(r.text)}</p>${toolBy(r.name)?`<button class="text-btn" data-detail="${toolBy(r.name).id}">특징·장단점 보기 ↗</button>`:''}</article>`).join('')}</div><section class="panel" style="margin-bottom:18px"><div class="panel-label">03 / OPERATION & TRADE-OFFS</div><h2>함께 설계해야 할 것들</h2><ul class="guide-list">${p.extras.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${p.alternatives.length?`<hr class="divider"><h3 style="font-size:13px">더 단순한 대안</h3><ul class="guide-list">${p.alternatives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${p.warnings.length?`<hr class="divider"><h3 style="font-size:13px">도입 전에 확인할 조건</h3><ul class="guide-list">${p.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<div class="lab-actions"><button class="btn soft" id="comparePlan">이 구조의 핵심 도구 비교 ⇄</button><button class="btn" id="exportPlan">설계 초안 내려받기 ↓</button></div></section><section class="panel"><div class="simulation-head"><div><div class="panel-label">04 / FLOW SIMULATION</div><h2 style="margin:0">데이터 흐름 재생</h2></div><button class="btn primary" id="runSimulation">▶ 흐름 재생</button></div><p class="scenario-note">샘플 120건이 단계별로 이동하는 모의 실행입니다. 실제 도구를 실행하거나 처리 성능·지연 시간을 측정하지 않습니다.</p><label class="check-line"><input type="checkbox" id="injectFailure"> 처리 중 일시 오류 1회 → 재시도 과정 보기</label><div class="mini-stats"><div class="mini-stat"><small>최종 반영</small><strong id="processed">0 / 120</strong></div><div class="mini-stat"><small>모의 재시도</small><strong id="retryCount">0</strong></div><div class="mini-stat"><small>진행 상태</small><strong id="simState" style="font-size:17px">대기</strong></div></div><div class="run-log" id="runLog" role="log" aria-label="모의 실행 로그">준비됨 · 흐름 재생을 눌러 데이터 이동과 재시도를 확인하세요.</div></section>`;$('#comparePlan').addEventListener('click',()=>{const names=[...new Set(p.nodes.map(n=>n.name))].filter(n=>toolBy(n));state.compared=names.slice(0,4).map(n=>toolBy(n).id);persist();navigate('compare');if(names.length>4)toast('흐름의 앞쪽 핵심 도구 4개를 비교함에 담았어요.')});$('#exportPlan').addEventListener('click',exportPlan);$('#runSimulation').addEventListener('click',runSimulation)}
function runSimulation(){if(simulationTimer){stopSimulation();$$('.arch-node').forEach(n=>n.classList.remove('running'));$('#simState').textContent='중지';$('#runSimulation').textContent='▶ 다시 재생';return}simulationStats={processed:0,retries:0,stage:0};const p=lastPlan,inject=$('#injectFailure').checked,log=$('#runLog');$('#processed').textContent='0 / 120';$('#retryCount').textContent='0';$('#simState').textContent='실행 중';$('#runSimulation').textContent='■ 중지';log.textContent='[모의 실행 시작] 샘플 120건 · 논리 흐름 재생\n';let batch=0,stage=0,failed=false;simulationTimer=setInterval(()=>{const current=p.nodes[stage];$$('.arch-node').forEach(n=>n.classList.remove('running'));const node=$(`[data-node="${stage}"]`);if(node)node.classList.add('running');if(inject&&!failed&&batch===1&&stage===Math.min(2,p.nodes.length-1)){failed=true;simulationStats.retries++;$('#retryCount').textContent=simulationStats.retries;log.textContent+=`[오류] ${current.name}: 일시 연결 실패. 같은 배치를 보존하고 재시도합니다.\n`;$('#simState').textContent='재시도 대기';log.scrollTop=log.scrollHeight;return}$('#simState').textContent='실행 중';log.textContent+=`[${String(batch+1).padStart(2,'0')}] ${current.name} · ${stage===p.nodes.length-1?'30건 반영':'30건 전달'}${failed&&batch===1&&stage===Math.min(2,p.nodes.length-1)?' · 재시도 성공':''}\n`;stage++;if(stage===p.nodes.length){stage=0;batch++;simulationStats.processed+=30;$('#processed').textContent=simulationStats.processed+' / 120';if(batch===4){stopSimulation();$('#simState').textContent='완료';$('#runSimulation').textContent='↻ 다시 재생';$$('.arch-node').forEach(n=>n.classList.remove('running'));log.textContent+='[완료] 120건 반영 · 실제 시스템에서는 키 기반 중복 방지와 체크포인트를 구현해야 합니다.\n'}}log.scrollTop=log.scrollHeight},300)}
function exportPlan(){const p=lastPlan;const text=`# Pipeline Atlas · 설계 초안\n\n서비스: ${cfg.platform}\n기준일: 2026-11-05\n방식: ${p.model}\n\n## 입력 조건\n${Object.entries(cfg).map(([k,v])=>k+': '+v).join('\n')}\n\n## 논리 흐름\n${p.nodes.map(n=>n.name).join(' → ')}\n실행 관리: ${p.orchestration}\n\n## 선택 이유\n${p.reasons.map(r=>'- '+r.name+': '+r.text).join('\n')}\n\n## 운영 설계\n${p.extras.map(x=>'- '+x).join('\n')}\n\n## 대안\n${p.alternatives.map(x=>'- '+x).join('\n')}\n\n## 검증할 조건\n${p.warnings.map(x=>'- '+x).join('\n')}\n\n실제 도구 실행·성능 검증 결과가 아닌 조건 기반 설계 가설입니다.\n\n## 공식 자료\n${[...new Set(p.nodes.map(n=>n.name))].map(toolBy).filter(Boolean).map(t=>'- '+t.name+': '+t.url).join('\n')}`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pipeline-design.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('설계 초안을 내려받았어요.')}
function methodology(){$('#detailBody').innerHTML=`<div class="modal-header"><h2>정보·선택 기준</h2><button class="close" data-close aria-label="닫기">×</button></div><div class="modal-content"><p>Pipeline Atlas는 기술을 배우고 설계 후보를 비교하는 학습용 지도입니다. 기준일은 2026년 11월 5일입니다.</p><div class="detail-block"><h3>도구 정보</h3><p>제품의 역할은 공식 문서를 참고한 요약이며, 장단점·학습 난이도·핵심 도구 표시는 정성적 편집 판단입니다. 점유율 순위나 측정된 성능 점수가 아닙니다. 각 도구의 상세 화면에 공식 자료 링크가 있습니다.</p></div><br><div class="detail-block"><h3>파이프라인 랩</h3><p>원본·반영 주기·운영 환경·규모·인력·소비자 수에 따른 브라우저 내부 규칙으로 구성합니다. 외부 AI나 실제 인프라에 연결하지 않습니다. 자유 입력은 알려진 키워드로 조건을 채우며, 이해하지 못한 설명은 기존 설정을 유지합니다. 구조는 가능한 설계 중 하나입니다.</p></div><br><div class="detail-block"><h3>도입 전 검증</h3><p>대표 데이터·쿼리로 처리 기한과 비용을 확인하고, 커넥터·버전·라이선스·네트워크·권한·장애 복구·삭제·중복 처리를 검증하세요. 모의 실행의 시간과 건수는 실제 제품의 처리 성능을 나타내지 않습니다.</p></div><br><div class="detail-block"><h3>저장되는 정보</h3><p>북마크와 비교함은 현재 브라우저에만 저장됩니다. 플랫폼 설명은 외부 서버로 전송하지 않으며, 페이지를 새로 열면 랩 입력은 초기화됩니다.</p></div></div>`;$('#detail').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.view){navigate(b.dataset.view);return}if(b.dataset.category){state.category=b.dataset.category;state.core=false;navigate('explore');return}if(b.dataset.detail){detail(b.dataset.detail);return}if(b.hasAttribute('data-close')){$('#detail').close();return}if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();renderExplore();navUpdate();return}if(b.dataset.compare){toggleCompare(b.dataset.compare);return}if(b.hasAttribute('data-clear-compare')){state.compared=[];persist();navUpdate();if(state.view==='compare')renderCompare();else if(state.view==='explore')renderCards();return}if(b.dataset.chip){if(b.dataset.chip==='core'){state.category='all';state.core=true}else{state.category=b.dataset.chip;state.core=false}render();return}if(b.dataset.preset){stopSimulation();Object.assign(cfg,PRESETS[b.dataset.preset],{preset:b.dataset.preset});renderLab();return}if(['resetFilters','emptyReset'].includes(b.id)){Object.assign(state,{category:'all',query:'',level:'all',delivery:'all',core:false,bookOnly:false});render();return}if(b.id==='bookmarkFilter'){state.bookOnly=!state.bookOnly;renderExplore();return}if(b.id==='methodology'){methodology();return}if(b.id==='mobileMenu'){$('.sidebar').classList.toggle('open')}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});
render();
